def will_it_fly(q, w):
    # The object flies if:
    # - It has at least two parts
    # - The total weight is less than or equal to w
    # - The object is unbalanced (left sum != right sum)
    if len(q) < 2:
        return False

    total_weight = sum(q)
    if total_weight > w:
        return False

    n = len(q)
    if n % 2 == 0:
        left = q[:n//2]
        right = q[n//2:]
    else:
        left = q[:n//2]
        right = q[n//2+1:]

    # The object must be unbalanced to fly
    return sum(left) != sum(right)

