def get_total_number_of_sequences(m: int, n: int) -> int:
    # dp[i][length]: number of sequences of length 'length' starting at element i
    # elements range from 1 to m
    # next element >= 2 * current element

    if n == 1:
        # Any element from 1 to m can start a sequence of length 1
        return m

    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base case: sequences of length 1 starting at i is 1
    for i in range(1, m + 1):
        dp[i][1] = 1

    for length in range(2, n + 1):
        # For each starting element i, sum over all next elements j >= 2*i
        # dp[i][length] = sum of dp[j][length-1] for all j >= 2*i and j <= m

        # To optimize summation, precompute suffix sums of dp[*][length-1]
        suffix_sum = [0] * (m + 2)  # suffix_sum[i] = sum of dp[i][length-1] to dp[m][length-1]
        for i in range(m, 0, -1):
            suffix_sum[i] = suffix_sum[i + 1] + dp[i][length - 1]

        for i in range(1, m + 1):
            start_j = 2 * i
            if start_j > m:
                dp[i][length] = 0
            else:
                dp[i][length] = suffix_sum[start_j]

    # Total sequences of length n = sum over all starting elements i
    return sum(dp[i][n] for i in range(1, m + 1))

