def find_solution(a, b, n):
    # Extended Euclidean Algorithm to find gcd and coefficients x, y such that a*x + b*y = gcd(a,b)
    def extended_gcd(a, b):
        if b == 0:
            return a, 1, 0
        gcd, x1, y1 = extended_gcd(b, a % b)
        x = y1
        y = x1 - (a // b) * y1
        return gcd, x, y

    gcd, x0, y0 = extended_gcd(a, b)
    if n % gcd != 0:
        return 'No solution'

    # Scale the solution by n // gcd
    x = x0 * (n // gcd)
    y = y0 * (n // gcd)
    return (x, y)

