def find_exponentio(bases, exponents):
    def power(base, exp):
        # Handle zero exponent
        if exp == 0:
            return 1.0

        # Handle negative exponent
        neg = exp < 0
        exp = abs(exp)

        result = 1.0
        current = base

        while exp > 0:
            if exp & 1:
                result *= current
            current *= current
            exp >>= 1

        return 1.0 / result if neg else result

    return tuple(power(b, e) for b, e in zip(bases, exponents))

