def get_total_number_of_sequences(start: int, limit: int, K: int) -> int:
    """
    Returns the total number of ordered sequences of length K starting at 'start',
    where each next element is at least double the previous one and all elements are <= limit.
    """
    from functools import lru_cache

    @lru_cache(None)
    def count_sequences(current: int, length: int) -> int:
        if length == K:
            return 1
        total = 0
        next_min = current * 2
        for next_val in range(next_min, limit + 1):
            total += count_sequences(next_val, length + 1)
        return total

    return count_sequences(start, 1)

