def find_Max(arr, start, end):
    # If there is only one element
    if start == end:
        return arr[start]
    # If the subarray is already sorted (no rotation)
    if arr[start] < arr[end]:
        return arr[end]

    mid = (start + end) // 2

    # Check if mid element is greater than its next element
    if mid < end and arr[mid] > arr[mid + 1]:
        return arr[mid]
    # Check if mid element is smaller than its previous element
    if mid > start and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]

    # Decide which half to search
    if arr[mid] > arr[start]:
        # Max is in the right half
        return find_Max(arr, mid + 1, end)
    else:
        # Max is in the left half
        return find_Max(arr, start, mid - 1)

