def next_smallest_palindrome(n: int) -> int:
    """
    Find the smallest palindrome strictly greater than n.
    """

    def is_palindrome(x: int) -> bool:
        s = str(x)
        return s == s[::-1]

    # If n < 9, the next palindrome is simply n+1
    if n < 9:
        return n + 1

    s = str(n)
    length = len(s)
    half = (length + 1) // 2  # middle index for odd length, half for even

    # Get the left half and mirror it to form a palindrome
    left_half = s[:half]
    if length % 2 == 0:
        palindrome = int(left_half + left_half[::-1])
    else:
        palindrome = int(left_half + left_half[-2::-1])

    if palindrome > n:
        return palindrome

    # Increment the left half and form palindrome again
    # Convert left half to int, add 1
    incremented = str(int(left_half) + 1)
    # If length changed after increment (like 99 + 1 = 100)
    if len(incremented) > len(left_half):
        # This means palindrome length increases by 1 or more, for example:
        # 99 -> 101
        if length % 2 == 0:
            palindrome = int(incremented + incremented[:-1][::-1])
        else:
            palindrome = int(incremented + incremented[:-2][::-1])
        return palindrome
    else:
        if length % 2 == 0:
            palindrome = int(incremented + incremented[::-1])
        else:
            palindrome = int(incremented + incremented[-2::-1])
        return palindrome

