def find_solution(a, b, n):
    from math import gcd

    def extended_gcd(aa, bb):
        # Returns (g, x, y) such that a*x + b*y = g = gcd(a,b)
        if bb == 0:
            return (aa, 1, 0)
        else:
            g, x1, y1 = extended_gcd(bb, aa % bb)
            x = y1
            y = x1 - (aa // bb) * y1
            return (g, x, y)

    g, x0, y0 = extended_gcd(a, b)

    # No solution if n not divisible by gcd(a,b)
    if n % g != 0:
        return None

    # Scale initial solution
    x0 *= n // g
    y0 *= n // g

    # If a and b are zero, special cases:
    if a == 0 and b == 0:
        return (0, 0) if n == 0 else None
    if a == 0:
        if n % b == 0 and n // b >= 0:
            return (0, n // b)
        else:
            return None
    if b == 0:
        if n % a == 0 and n // a >= 0:
            return (n // a, 0)
        else:
            return None

    # Find parameter t such that:
    # x = x0 + (b/g)*t
    # y = y0 - (a/g)*t
    # We want x >= 0 and y >= 0

    # Calculate bounds for t from inequalities:
    # x0 + (b/g)*t >= 0  =>  t >= -x0 * (g/b)
    # y0 - (a/g)*t >= 0  =>  t <= y0 * (g/a)

    # But be careful with signs of a and b
    # To avoid float division, do integer division with care

    bg = b // g
    ag = a // g

    # Inequalities:
    # t >= ceil(-x0 / bg) if bg > 0 else t <= floor(-x0 / bg)
    # t <= floor(y0 / ag) if ag > 0 else t >= ceil(y0 / ag)

    # Define helper for ceiling division:
    def div_ceil(num, den):
        if den == 0:
            return None
        if den > 0:
            return (num + den - 1) // den
        else:
            return (num + den + 1) // den

    def div_floor(num, den):
        if den == 0:
            return None
        if den > 0:
            return num // den
        else:
            return num // den

    # Compute bounds for t
    if bg != 0:
        if bg > 0:
            t_min = div_ceil(-x0, bg)
        else:
            t_max = div_floor(-x0, bg)
    else:
        # bg == 0 means b == 0, handled above
        t_min = None
        t_max = None

    if ag != 0:
        if ag > 0:
            t_max_2 = div_floor(y0, ag)
        else:
            t_min_2 = div_ceil(y0, ag)
    else:
        t_min_2 = None
        t_max_2 = None

    # Merge bounds:
    # Start with no bounds:
    t_lower = -float('inf')
    t_upper = float('inf')

    if bg != 0:
        if bg > 0:
            t_lower = max(t_lower, t_min)
        else:
            t_upper = min(t_upper, t_max)
    if ag != 0:
        if ag > 0:
            t_upper = min(t_upper, t_max_2)
        else:
            t_lower = max(t_lower, t_min_2)

    if t_lower > t_upper:
        return None  # No integer t satisfies both inequalities

    # We want any integer t in [t_lower, t_upper]
    # Choose t = t_lower rounded up to integer
    # Since t_lower and t_upper might be floats, but we constructed with integer divisions,
    # they should be integers or infinite.

    # If t_lower is -inf, pick t = 0 if it fits, else t_upper if finite
    # But better to pick t = max(t_lower, 0), if feasible

    # Try t = max(t_lower, 0)
    if t_lower == -float('inf'):
        candidate_ts = [0]
    else:
        candidate_ts = [t_lower]

    # Also consider if 0 is in range, try t=0 first for simplicity
    if t_lower <= 0 <= t_upper:
        candidate_ts = [0]
    else:
        candidate_ts = [int(t_lower)]

    # Try candidate t values until find a valid one
    # Because bounds are tight, try t_lower and t_upper integer values
    # Also try t_lower rounded up and t_upper rounded down

    candidates = set()

    if t_lower != -float('inf'):
        candidates.add(int(t_lower))
        # If t_lower is not integer, try next integer above
        if t_lower != int(t_lower):
            candidates.add(int(t_lower)+1)
    if t_upper != float('inf'):
        candidates.add(int(t_upper))
        # If t_upper is not integer, try next integer below
        if t_upper != int(t_upper):
            candidates.add(int(t_upper)-1)
    # Also try zero if in bounds
    if t_lower <= 0 <= t_upper:
        candidates.add(0)

    candidates = [t for t in candidates if t_lower <= t <= t_upper]

    for t in candidates:
        x = x0 + bg * t
        y = y0 - ag * t
        if x >= 0 and y >= 0:
            return (x, y)

    return None

def next_power_of_2(n: int) -> int:
    if n <= 1:
        # For n <= 1, return the smallest power of two >= n, which is 1
        return 1

    # Check if n is a power of two
    if (n & (n - 1)) == 0:
        # If n is a power of two and greater than 1, return n itself
        return n

    # Find the smallest power of two greater than or equal to n
    power = 1
    while power < n:
        power <<= 1

    return power

