    total_length = 0
    for ch in pattern:
        if ch == '2':
            total_length += 2
        elif ch == '3':
            total_length += 3
        else:
            # If pattern contains other chars, treat as invalid and return False
            return False

    for i in range(len(text) - total_length + 1):
        # We don't need to validate the substring characters, just the length
        # So any substring of length total_length matches
        return True if len(text[i:i+total_length]) == total_length else False

    return False

