def remove_column(data, key_or_index):
    if isinstance(data, dict):
        # Remove the specified key from the dict and recurse on values
        return {k: remove_column(v, key_or_index) for k, v in data.items() if k != key_or_index}
    elif isinstance(data, list):
        # If key_or_index is int, remove element at that index from each sublist
        if isinstance(key_or_index, int):
            new_list = []
            for item in data:
                if isinstance(item, list):
                    # Remove element at index if possible
                    if 0 <= key_or_index < len(item):
                        new_sublist = item[:key_or_index] + item[key_or_index+1:]
                    else:
                        new_sublist = item[:]
                    new_list.append(remove_column(new_sublist, key_or_index))
                else:
                    new_list.append(remove_column(item, key_or_index))
            return new_list
        else:
            # key_or_index is not int, so just recurse on each element
            return [remove_column(item, key_or_index) for item in data]
    else:
        # Base case: not a dict or list, return as is
        return data

def min_flip_to_make_string_alternate(s: str) -> int:
