    # pattern1: starts with '0' -> "010101..."
    # pattern2: starts with '1' -> "101010..."

    flips_pattern1 = 0
    flips_pattern2 = 0

    for i, ch in enumerate(s):
        expected_char_pattern1 = '0' if i % 2 == 0 else '1'
        expected_char_pattern2 = '1' if i % 2 == 0 else '0'

        if ch != expected_char_pattern1:
