def lcm(a: int, b: int) -> int:
    if a == 0 or b == 0:
        return 0
    # Use absolute values to ensure positive LCM
    a, b = abs(a), abs(b)

    # Compute gcd using Euclidean algorithm
    def gcd(x, y):
        while y:
            x, y = y, x % y
        return x

    return a // gcd(a, b) * b

