def compute_Last_Digit(a: int, b: int) -> int:
    if a == b:
        return 1
    last_digit = 1
    for x in range(a + 1, b + 1):
        last_digit = (last_digit * (x % 10)) % 10
        # If last_digit becomes 0, no need to continue since it won't change
        if last_digit == 0:
            break
    return last_digit

def zip_tuples(t1, t2):
    if len(t1) <= len(t2):
        shorter, longer = t1, t2
    else:
        shorter, longer = t2, t1

    # The output length matches the length of the first tuple (t1)
    result = []
    len_shorter = len(shorter)
    for i in range(len(t1)):
        # cycle through the shorter tuple
        elem_shorter = shorter[i % len_shorter]
        elem_longer = longer[i] if len(longer) > i else longer[i % len(longer)]

        # Determine which element corresponds to which tuple
        if len(t1) <= len(t2):
            pair = (elem_shorter, elem_longer)
        else:
            pair = (elem_longer, elem_shorter)
        result.append(pair)

    return tuple(result)

