def next_smallest_palindrome(num: int) -> int:
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    s = str(num + 1)  # start checking from the next number after num
    length = len(s)

    # If all 9's, the next palindrome is 10..01
    if all(ch == '9' for ch in s):
        return int('1' + ('0' * (length - 1)) + '1')

    while True:
        if is_palindrome(s):
            return int(s)

        # Generate palindrome by mirroring left to right
        half_len = (len(s) + 1) // 2
        left = s[:half_len]
        if len(s) % 2 == 0:
            pal_candidate = left + left[::-1]
        else:
            pal_candidate = left + left[-2::-1]

        if int(pal_candidate) > int(s):
            s = pal_candidate
        else:
            # increment the left half and mirror again
            new_left = str(int(left) + 1)
            # handle length change after increment
            if len(new_left) > len(left):
                # e.g. 999 + 1 = 1000, length increased
                s = new_left + new_left[-2::-1] if len(s) % 2 else new_left + new_left[::-1]
            else:
                if len(s) % 2 == 0:
                    s = new_left + new_left[::-1]
                else:
                    s = new_left + new_left[-2::-1]

