def permute_string(s):
    result = []
    def backtrack(path, used):
        if len(path) == len(s):
            result.append("".join(path))
            return
        for i in range(len(s)):
            if used[i]:
                continue
            used[i] = True
            path.append(s[i])
            backtrack(path, used)
            path.pop()
            used[i] = False
    backtrack([], [False]*len(s))
    return result

