def find_Max(arr, low, high):
    # If the array has only one element
    if low == high:
        return arr[low]

    # If the array is not rotated (the subarray is sorted)
    if arr[low] < arr[high]:
        return arr[high]

    mid = (low + high) // 2

    # Check if mid element is the maximum
    if mid < high and arr[mid] > arr[mid + 1]:
        return arr[mid]

    # Check if mid-1 element is the maximum
    if mid > low and arr[mid] < arr[mid - 1]:
        return arr[mid - 1]

    # Decide whether to go to left half or right half
    if arr[mid] > arr[low]:
        return find_Max(arr, mid + 1, high)
    else:
        return find_Max(arr, low, mid - 1)

