def get_noOfways(n: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return 1
    # ways[i] will store number of ways to tile 2 x i board
    ways = [0] * (n + 1)
    ways[0] = 1  # 1 way to tile empty board (base case)
    ways[1] = 1  # only vertical placement possible for 2x1 board
    for i in range(2, n + 1):
        ways[i] = ways[i - 1] + ways[i - 2]
    return ways[n]

