def get_total_number_of_sequences(m, n):
    # dp[pos][val]: number of sequences of length pos ending with val
    # pos ranges from 1 to n (length)
    # val ranges from 1 to m (value of element)
    if n == 0:
        return 0
    if n == 1:
        # Any value from 1 to m can be the sequence of length 1
        return m

    dp = [ [0]*(m+1) for _ in range(n+1) ]

    # Base case: sequences of length 1
    for val in range(1, m+1):
        dp[1][val] = 1

    for pos in range(2, n+1):
        for val in range(1, m+1):
            # For current val, find all prev_val where val >= 2 * prev_val
            # i.e. prev_val <= val // 2
            max_prev = val // 2
            if max_prev >= 1:
                dp[pos][val] = sum(dp[pos-1][prev_val] for prev_val in range(1, max_prev+1))

    return sum(dp[n][val] for val in range(1, m+1))

def even_binomial_Coeff_Sum(n: int) -> int:
    # Using the identity:
    # sum_{k even} C(n, k) = 2^(n-1) + (1 + (-1)^n)/2 * 2^(n-1)
    # which simplifies to:
    # if n even: sum = 2^(n-1) + 2^(n-1) = 2^n
    # if n odd: sum = 2^(n-1)
    # More simply, sum of binomial coefficients at even indices = 2^(n-1) + (1/2)(1+(-1)^n)*2^(n-1)
    # But this equals (2^(n) + (1+(-1)^n)*2^(n-1)) / 2 = (2^n + (1+(-1)^n)*2^(n-1))/2
    # Alternatively, the sum of even binomial coefficients is (2^(n) + (1+(-1)^n)*2^{n-1})/2
    # But simpler: sum_even = 2^{n-1} if n odd, 2^n if n even
    # Or more simply: sum_even = 2^{n-1} * (1 + (-1)^n)
    # since (1 + (-1)^n) is 2 if n even, 0 if n odd.
    # However, for n odd, sum_even = 2^{n-1}
    # So better to use the known identity:
    # sum_{k even} C(n,k) = 2^{n-1} + (1/2)(1+(-1)^n)*2^{n-1} = 2^{n-1} * (1 + (1+(-1)^n)/2) = 2^{n-1} * ( (2 + (-1)^n)/2)
    # Let's just use the well-known formula: sum_even = 2^{n-1} if n odd, 2^n if n even.

    if n % 2 == 0:
        return 2 ** (n)
    else:
        return 2 ** (n - 1)

