def lucky_num(n):
    if n == 0:
        return []
    # Start with a large enough list to generate n lucky numbers
    # We'll guess an upper bound and increase if needed
    limit = 2 * n * n  # initial guess
    while True:
        numbers = list(range(1, limit + 1))
        idx = 1  # start from the second element (index 1), since the first sieve value is numbers[0] = 1
        while idx < len(numbers):
            step = numbers[idx]
            if step > len(numbers):
                break
            # Remove every step-th number starting from index step-1 (0-based)
            numbers = [num for i, num in enumerate(numbers) if (i + 1) % step != 0]
            idx += 1
        if len(numbers) >= n:
            return numbers[:n]
        limit *= 2

