def compute_Last_Digit(a: int, b: int) -> int:
    # Compute the last digit of product (a+1) * (a+2) * ... * b

    # If a == b, the product is empty, so the result is 1 (last digit 1)
    if a == b:
        return 1

    last_digit = 1
    for num in range(a+1, b+1):
        last_digit = (last_digit * (num % 10)) % 10

        # Early stop if last digit is 0, since multiplying more will keep it 0
        if last_digit == 0:
            return 0

    return last_digit

