def next_smallest_palindrome(num: int) -> int:
    s = str(num)
    length = len(s)

    # Helper to check palindrome
    def is_palindrome(x: str) -> bool:
        return x == x[::-1]

    # If num < 9, next palindrome is num+1 (since single digit palindromes are all digits)
    # But since next palindrome must be strictly greater, for num=9 => 11
    if num < 9:
        return num + 1

    # Convert num+1 to string to start searching from strictly greater number
    num += 1
    s = str(num)
    length = len(s)

    while True:
        if is_palindrome(s):
            return int(s)
        num += 1
        s = str(num)

def find_solution(a, b, n):
    x = 0
    while True:
        remainder = n - a * x
        if remainder % b == 0:
            y = remainder // b
            return (x, y)
        x += 1
        # To avoid infinite loop when no solution:
        # If b == 0, then equation is a*x = n, so only x matters.
        # But since we scan x from 0 up, if no solution found before x > n//a + 1, stop.
        # Similarly, if a == 0 and b != 0, we can find y directly.
        # To keep it simple, let's limit the search to a reasonable range.
        # Because if a > 0, once a*x > n and remainder negative, no need to continue.
        if a > 0 and a * x > n:
            break
        # If a == 0:
        if a == 0:
            # Then the equation is b*y = n
            if n % b == 0:
                return (0, n // b)
            else:
                break
        # If a < 0, and scanning upwards x from 0, a*x decreases, so remainder increases
        # but since we expect smallest non-negative x, just limit search to some max
        if x > abs(n) + abs(b):
            break

    return 'No solution'

def next_power_of_2(n: int) -> int:
    if n <= 0:
        return 1
    # If n is already a power of two, return n
    if (n & (n - 1)) == 0:
        return n
    power = 1
    while power < n:
        power <<= 1
    return power

