def find_Max(nums):
    if not nums:
        return None

    left, right = 0, len(nums) - 1

    # If the array is not rotated (the first element is less than the last),
    # then the last element is the max.
    if nums[left] < nums[right]:
        return nums[right]

    while left < right:
        mid = (left + right) // 2
        # If mid element is greater than the element at right,
        # max must be in the right half including mid.
        if nums[mid] > nums[right]:
            left = mid + 1
        else:
            right = mid

    # At the end of the loop, left points to the smallest element,
    # so the max element is just before it in the rotated array.
    return nums[left - 1]

