def substract_elements(t1, t2):
    if isinstance(t1, int) and isinstance(t2, int):
        return t1 - t2
    if isinstance(t1, tuple) and isinstance(t2, tuple):
        if len(t1) != len(t2):
            raise ValueError("Tuples must have the same structure and length")
        return tuple(substract_elements(a, b) for a, b in zip(t1, t2))
    raise TypeError("Both arguments must be integers or tuples with the same structure")

def lucky_num(n):
    numbers = list(range(1, 10**6))  # start with a large enough list
    idx = 1  # start from second element (index 1)
    while idx < len(numbers) and len(numbers) < n or len(numbers) > n:
        step = numbers[idx]
        if step > len(numbers):
            break
        # remove every step-th number
        del numbers[step-1::step]
        idx += 1
        if len(numbers) >= n:
            break
    return numbers[:n]

def get_noOfways(n: int) -> int:
    if n == 0:
        return 0
    if n == 1:
        return 1
    dp = [0] * (n + 1)
    dp[0] = 1  # empty board has 1 way (do nothing)
    dp[1] = 1  # one vertical tile
    for i in range(2, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]
